CREATE TABLE public.companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9][a-z0-9-]{2,59}$'), cnpj text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','suspended')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.companies TO authenticated; GRANT ALL ON public.companies TO service_role;
ALTER TABLE public.companies ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.company_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id), user_id uuid NOT NULL UNIQUE, role text NOT NULL CHECK (role IN ('owner','operator')), approved boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.company_roles TO authenticated; GRANT ALL ON public.company_roles TO service_role;
ALTER TABLE public.company_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.platform_roles (user_id uuid PRIMARY KEY, role text NOT NULL CHECK (role = 'admin'));
GRANT SELECT ON public.platform_roles TO authenticated; GRANT ALL ON public.platform_roles TO service_role;
ALTER TABLE public.platform_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_platform_role ON public.platform_roles FOR SELECT TO authenticated USING(user_id = auth.uid());
CREATE FUNCTION public.is_platform_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.platform_roles WHERE user_id = auth.uid() AND role = 'admin') $$;
CREATE FUNCTION public.current_company_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT company_id FROM public.company_roles WHERE user_id = auth.uid() LIMIT 1 $$;
CREATE FUNCTION public.can_manage_company(_company_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.company_roles r JOIN public.companies c ON c.id = r.company_id WHERE r.user_id = auth.uid() AND r.company_id = _company_id AND r.approved AND c.status = 'approved') $$;
CREATE FUNCTION public.is_company_owner(_company_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.company_roles WHERE user_id = auth.uid() AND company_id = _company_id AND role = 'owner' AND approved) $$;
CREATE POLICY company_read ON public.companies FOR SELECT TO authenticated USING (id = public.current_company_id() OR public.is_platform_admin());
CREATE POLICY member_read ON public.company_roles FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.is_company_owner(company_id));
INSERT INTO public.companies(name,slug,cnpj,status) VALUES ('GUANABARA PRIME TRANSPORTES LTDA','guanabara-prime','','approved');
INSERT INTO public.company_roles(company_id,user_id,role,approved) SELECT c.id,r.user_id,'owner',true FROM public.user_roles r CROSS JOIN public.companies c WHERE r.role = 'admin' AND c.slug = 'guanabara-prime';
INSERT INTO public.platform_roles(user_id,role) SELECT r.user_id,'admin' FROM public.user_roles r JOIN auth.users u ON u.id = r.user_id WHERE r.role = 'admin' ORDER BY u.created_at,u.id LIMIT 1;
CREATE OR REPLACE FUNCTION public.handle_first_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN RETURN new; END $$;
ALTER TABLE public.shipments ADD COLUMN company_id uuid REFERENCES public.companies(id) DEFAULT public.current_company_id();
UPDATE public.shipments SET company_id = (SELECT id FROM public.companies WHERE slug = 'guanabara-prime') WHERE company_id IS NULL;
CREATE INDEX shipments_company_idx ON public.shipments(company_id,created_at DESC);
DROP POLICY "admin all shipments" ON public.shipments;
CREATE POLICY tenant_shipments ON public.shipments FOR ALL TO authenticated USING(public.can_manage_company(company_id)) WITH CHECK(public.can_manage_company(company_id));
DROP POLICY "admin all events" ON public.shipment_events;
CREATE POLICY tenant_events ON public.shipment_events FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.shipments s WHERE s.id = shipment_id AND public.can_manage_company(s.company_id))) WITH CHECK(EXISTS(SELECT 1 FROM public.shipments s WHERE s.id = shipment_id AND public.can_manage_company(s.company_id)));
CREATE FUNCTION public.register_company(_name text, _slug text, _cnpj text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE cid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na sua conta'; END IF; IF EXISTS(SELECT 1 FROM public.company_roles WHERE user_id = auth.uid()) THEN RAISE EXCEPTION 'Conta já vinculada a uma transportadora'; END IF; IF length(trim(_name)) < 3 OR length(regexp_replace(_cnpj,'\D','','g')) <> 14 THEN RAISE EXCEPTION 'Informe nome e CNPJ de 14 dígitos'; END IF; INSERT INTO public.companies(name,slug,cnpj) VALUES(trim(_name),lower(trim(_slug)),regexp_replace(_cnpj,'\D','','g')) RETURNING id INTO cid; INSERT INTO public.company_roles(company_id,user_id,role,approved) VALUES(cid,auth.uid(),'owner',true); RETURN cid; END $$;
CREATE FUNCTION public.join_company(_slug text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE cid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na sua conta'; END IF; SELECT id INTO cid FROM public.companies WHERE slug = lower(trim(_slug)) AND status = 'approved'; IF cid IS NULL THEN RAISE EXCEPTION 'Transportadora não encontrada'; END IF; INSERT INTO public.company_roles(company_id,user_id,role) VALUES(cid,auth.uid(),'operator'); END $$;
CREATE FUNCTION public.set_company_status(_id uuid,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT public.is_platform_admin() THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF _status NOT IN ('approved','suspended') THEN RAISE EXCEPTION 'Status inválido'; END IF; UPDATE public.companies SET status = _status WHERE id = _id; END $$;
CREATE FUNCTION public.set_member_access(_user_id uuid,_approved boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT public.is_company_owner(public.current_company_id()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; UPDATE public.company_roles SET approved = _approved WHERE user_id = _user_id AND company_id = public.current_company_id() AND role = 'operator'; IF NOT FOUND THEN RAISE EXCEPTION 'Membro não encontrado ou proprietário protegido'; END IF; END $$;
CREATE FUNCTION public.tracking_companies() RETURNS TABLE(name text,slug text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT name,slug FROM public.companies WHERE status = 'approved' ORDER BY name $$;
CREATE OR REPLACE FUNCTION public.track_shipment(_nfe_key text DEFAULT NULL,_number text DEFAULT NULL,_doc text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$ BEGIN RETURN NULL; END $$;
CREATE FUNCTION public.track_company_shipment(_company_slug text,_nfe_key text DEFAULT NULL,_number text DEFAULT NULL,_doc text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$ DECLARE s public.shipments; cid uuid; k text; d text; n text; BEGIN SELECT id INTO cid FROM public.companies WHERE slug = _company_slug AND status = 'approved'; IF cid IS NULL THEN RETURN NULL; END IF; k := regexp_replace(coalesce(_nfe_key,''),'\D','','g'); d := regexp_replace(coalesce(_doc,''),'\D','','g'); n := upper(trim(coalesce(_number,''))); IF length(k) = 44 THEN SELECT * INTO s FROM public.shipments WHERE company_id = cid AND regexp_replace(coalesce(nfe_key,''),'\D','','g') = k ORDER BY created_at DESC LIMIT 1; ELSIF n <> '' AND length(d) IN (11,14) THEN SELECT * INTO s FROM public.shipments WHERE company_id = cid AND regexp_replace(customer_doc,'\D','','g') = d AND (upper(tracking_code) = n OR (n ~ '^[0-9]+$' AND ltrim(coalesce(nfe_number,''),'0') = ltrim(n,'0'))) ORDER BY created_at DESC LIMIT 1; ELSE RETURN NULL; END IF; IF s.id IS NULL THEN RETURN NULL; END IF; RETURN jsonb_build_object('tracking_code',s.tracking_code,'nfe_number',s.nfe_number,'customer_name',split_part(s.customer_name,' ',1),'origin',s.origin,'destination',s.destination,'status',s.status,'estimated_delivery',s.estimated_delivery,'updated_at',s.updated_at,'events',coalesce((SELECT jsonb_agg(jsonb_build_object('status',e.status,'location',e.location,'note',e.note,'created_at',e.created_at) ORDER BY e.created_at DESC) FROM public.shipment_events e WHERE e.shipment_id = s.id),'[]'::jsonb)); END $$;
REVOKE ALL ON FUNCTION public.register_company(text,text,text),public.join_company(text),public.set_company_status(uuid,text),public.set_member_access(uuid,boolean),public.is_platform_admin(),public.current_company_id(),public.can_manage_company(uuid),public.is_company_owner(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.register_company(text,text,text),public.join_company(text),public.set_company_status(uuid,text),public.set_member_access(uuid,boolean),public.is_platform_admin(),public.current_company_id(),public.can_manage_company(uuid),public.is_company_owner(uuid) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.tracking_companies(),public.track_company_shipment(text,text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.tracking_companies(),public.track_company_shipment(text,text,text,text) TO anon,authenticated,service_role;
COMMENT ON FUNCTION public.track_shipment(text,text,text) IS 'DEPRECATED: use tenant-scoped track_company_shipment';
COMMENT ON TABLE public.user_roles IS 'DEPRECATED: company_roles and platform_roles own KargaRadar permissions';